package glitch

import data.glitch_lib

sensitive_attributes := {"password", "secret", "token", "api_key", "apikey", "private_key", "privatekey", "auth", "credential", "key", "sha512_password", "sha512password"}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    all_vars := glitch_lib.all_variables(parent)
    var := all_vars[_]
    name_lower := lower(var.name)
    contains_sensitive_keyword(name_lower)
    var.value.ir_type == "String"
    var.value.value != ""
    not is_reference(var.value)
    result := {
        "type": "sec_hard_secr",
        "element": var,
        "path": parent.path,
        "description": "Hard-coded credential found in variable. (CWE-798)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    all_attrs := glitch_lib.all_attributes(parent)
    attr := all_attrs[_]
    name_lower := lower(attr.name)
    contains_sensitive_keyword(name_lower)
    attr.value.ir_type == "String"
    attr.value.value != ""
    not is_reference(attr.value)
    result := {
        "type": "sec_hard_secr",
        "element": attr,
        "path": parent.path,
        "description": "Hard-coded credential found in attribute. (CWE-798)"
    }
}

contains_sensitive_keyword(name) {
    keyword := sensitive_attributes[_]
    contains(name, keyword)
}

is_reference(node) {
    node.ir_type == "VariableReference"
} else {
    node.ir_type == "FunctionCall"
} else {
    node.ir_type == "MethodCall"
}
